def longest_palindrome(text):
    best_start, best_length = 0, 0

    def expand(left, right):
        # grow outwards while the two ends match; return the length of the palindrome found
        while left >= 0 and right < len(text) and text[left] == text[right]:
            left -= 1
            right += 1
        return right - left - 1

    for centre in range(len(text)):
        for length in (expand(centre, centre), expand(centre, centre + 1)):    # odd, then even
            if length > best_length:                  # strictly longer, so the leftmost of equals is kept
                best_start, best_length = centre - (length - 1) // 2, length
    return text[best_start:best_start + best_length]
